use vstd::prelude::*;

verus! {

fn swap_first_and_last(a: &Vec<i32>) -> (result: Vec<i32>)
    requires
        // Input array is non‐empty
        a.len() > 0,
    ensures
        // Result has the same length as the input
        result.len() == a.len(),
        // The first element of the result is the last of the input
        result[0] == a[a.len() - 1],
        // The last element of the result is the first of the input
        result[a.len() - 1] == a[0],
        // All interior elements remain unchanged
        forall |i: nat| 1 <= i && i < a.len() - 1 ==> result[i] == a[i],
{
    let n: usize = a.len();
    let mut result: Vec<i32> = Vec::new();

    // 1) Push a[n-1] as the new first element
    result.push(a[n - 1]);

    // 2) Copy over any interior elements a[1..n-1]
    let mut i: usize = 1;
    while i < n - 1
        invariant
            // we've copied exactly `i` elements so far
            result.len() == i,
            // and each one matches: for all j< i, result[j] == a[j]
            forall |j: nat| 1 <= j && j < i ==> result[j] == a[j],
        decreases (n - 1) - i
    {
        result.push(a[i]);
        i += 1;
    }

    // 3) Finally, if the vector had more than one element,
    //    push the original first element at the end.
    if n > 1 {
        result.push(a[0]);
    }

    result
}

} // end verus!

